This component does too much. Refactor it:
```jsx
function UserDashboard({ userId }) {
  const [user, setUser] = useState(null);
  const [posts, setPosts] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch(`/api/users/${userId}`)
      .then(r => r.json())
      .then(u => { setUser(u); return fetch(`/api/users/${userId}/posts`); })
      .then(r => r.json())
      .then(setPosts)
      .catch(setError);
  }, [userId]);

  if (error) return <p>Error: {error.message}</p>;
  if (!user) return <p>Loading...</p>;

  return (
    <div style={{ padding: 20, background: '#f0f0f0' }}>
      <h1 style={{ color: 'blue' }}>{user.name}</h1>
      <p style={{ fontSize: 14 }}>{user.email}</p>
      <ul>
        {posts.map(p => <li key={p.id}>{p.title}</li>)}
      </ul>
    </div>
  );
}
```

This component fetches data sequentially. Optimize it:
